}

/// A response model generated by the MN Assistant Copilot
class CopilotResponse {
  final String text;
  final CopilotActionType actionType;
  final String? actionLabel;
  final List<String> relatedQuestions;

  CopilotResponse({
    required this.text,
    this.actionType = CopilotActionType.none,
    this.actionLabel,
    this.relatedQuestions = const [],
  });
}

/// In-App Grounded Personalized AI Copilot Engine ("MN Assistant")
/// Provides real-time, personalized, intelligent Q&A grounded on:
/// - Active logged-in user identity (name, role, department)
/// - Live runtime to-dos, role checklists, and shift/attendance history
/// - 7 Pillars personal records and emergency permission quotas
/// - Official Company SOPs & HR policy matrices
/// - Resilient NLP matching for human typing errors, mobile shorthand, and broken grammar
class MnAiCopilotService {
  /// Levenshtein distance algorithm for calculating character differences
  static int _levenshtein(String a, String b) {
    if (a == b) return 0;
    if (a.isEmpty) return b.length;
    if (b.isEmpty) return a.length;

    List<int> v0 = List<int>.generate(b.length + 1, (i) => i);
    List<int> v1 = List<int>.filled(b.length + 1, 0);

    for (int i = 0; i < a.length; i++) {
      v1[0] = i + 1;
      for (int j = 0; j < b.length; j++) {
        final cost = (a[i] == b[j]) ? 0 : 1;
        v1[j + 1] = [
          v1[j] + 1,
          v0[j + 1] + 1,
          v0[j] + cost,
        ].reduce((curr, next) => curr < next ? curr : next);
      }
      for (int j = 0; j < v0.length; j++) {
        v0[j] = v1[j];
      }
    }
    return v1[b.length];
  }

  /// Expands common chat shorthand, slang, SMS acronyms, and phonetic variations
  static String normalizeHumanInput(String raw) {
    String text = raw.trim().toLowerCase();

    // Map common mobile typing abbreviations & slang to normalized vocabulary
    final shorthandMap = {
      RegExp(r'\b(pls|plz|plse)\b'): 'please',
      RegExp(r'\b(wht|wat|wt)\b'): 'what',
      RegExp(r'\b(hw|hwo)\b'): 'how',
      RegExp(r'\b(mny|mch)\b'): 'many',
      RegExp(r'\b(u|yu)\b'): 'you',
      RegExp(r'\b(r|ar)\b'): 'are',
      RegExp(r'\b(bcoz|cuz|coz)\b'): 'because',
      RegExp(r'\b(abt)\b'): 'about',
      RegExp(r'\b(msg|msgs)\b'): 'message',
      RegExp(r'\b(info)\b'): 'information',
      RegExp(r'\b(dr|doc|doctr)\b'): 'doctor',
      RegExp(r'\b(hosp|hosptl)\b'): 'hospital',
      RegExp(r'\b(med|meds|medicl|medicall)\b'): 'medical',
      RegExp(r'\b(prmsn|prms|perm|permisson|permision|permissin|permissino)\b'): 'permission',
      RegExp(r'\b(atnd|atndnc|attndnc|atendance|attendence|attandance)\b'): 'attendance',
      RegExp(r'\b(pnch|pnchin|pnchout|punc|punchin|punchout)\b'): 'punch',
      RegExp(r'\b(shft|shif)\b'): 'shift',
      RegExp(r'\b(tmg|tmgs|timng|timngs)\b'): 'timing',
      RegExp(r'\b(blkr|blckr|bloker|blokers|blokr)\b'): 'blocker',
      RegExp(r'\b(fotografy|photograpy|photogrphy|camer|camra|shote)\b'): 'photography',
      RegExp(r'\b(insta|instgram|instgaram|rel|reels)\b'): 'instagram',
      RegExp(r'\b(ordr|oreder|odr|ordrs)\b'): 'order',
      RegExp(r'\b(pilr|pilar|piler|pilrs|pillers)\b'): 'pillar',
      RegExp(r'\b(wrk|wrks|tsk|tsks|to-do|todo)\b'): 'task',
      RegExp(r'\b(gatepass|gate pass)\b'): 'permission',
      RegExp(r'\b(halfday|half day)\b'): 'leave',
      RegExp(r'\b(go out|early go|early out|urgent out)\b'): 'permission',
      RegExp(r'\b(whoami|who m i)\b'): 'who am i',
      RegExp(r'\b(inout|in out|in-out)\b'): 'punch',
    };

    shorthandMap.forEach((pattern, replacement) {
      text = text.replaceAll(pattern, replacement);
    });

    return text;
  }

  /// Basic word stemmer to reduce plurals and grammatical conjugations to root forms
  static String stemWord(String word) {
    String w = word.trim().toLowerCase();
    if (w.endsWith('ing') && w.length > 5) return w.substring(0, w.length - 3);
    if (w.endsWith('ed') && w.length > 4) return w.substring(0, w.length - 2);
    if (w.endsWith('es') && w.length > 4) return w.substring(0, w.length - 2);
    if (w.endsWith('s') && w.length > 3 && !w.endsWith('ss')) return w.substring(0, w.length - 1);
    return w;
  }

  /// Calculates a confidence score (0 to 100) for a given intent based on keywords and phrases
  static int scoreIntent({
    required String normalizedInput,
    required List<String> tokenWords,
    required List<String> stemWords,
    required List<String> phrases,
    required List<String> primaryKeywords,
    required List<String> secondaryKeywords,
  }) {
    int score = 0;

    // 1. Exact phrase presence (+30 points)
    for (final phrase in phrases) {
      if (normalizedInput.contains(phrase.toLowerCase())) {
        score += 30;
      }
    }

    // 2. Primary keyword match (+12 points exact, +8 points fuzzy)
    for (final pKey in primaryKeywords) {
      final pRoot = stemWord(pKey);
      if (tokenWords.contains(pKey) || stemWords.contains(pRoot)) {
        score += 14;
      } else {
        // Levenshtein fuzzy match
        for (final word in tokenWords) {
          if (word.length >= 4 && pKey.length >= 4) {
            final maxDist = pKey.length >= 7 ? 2 : 1;
            if (_levenshtein(word, pKey) <= maxDist) {
              score += 9;
              break;
            }
          }
        }
      }
    }

    // 3. Secondary keyword match (+6 points exact, +4 points fuzzy)
    for (final sKey in secondaryKeywords) {
      final sRoot = stemWord(sKey);
      if (tokenWords.contains(sKey) || stemWords.contains(sRoot)) {
        score += 6;
      } else {
        for (final word in tokenWords) {
          if (word.length >= 4 && sKey.length >= 4) {
            if (_levenshtein(word, sKey) <= 1) {
              score += 4;
              break;
            }
          }
        }
      }
    }

    return score;
  }

  /// Extracts clean preferred first/display name from full employee name
  static String extractFirstName(String fullName) {
    final parts = fullName
        .trim()
        .split(' ')
        .where((p) => p.isNotEmpty && p.length > 2 && !p.endsWith('.'))
        .toList();
    if (parts.isNotEmpty) return parts.first;
    return fullName.trim();
  }

  /// Formulates the initial greeting personalized to the logged-in employee
  static String buildWelcomeMessage(EcosystemProvider eco) {
    final emp = eco.currentEmployee;
    final firstName = extractFirstName(emp.name);
    final myTodos = eco.todayPendingTodosCount;
    final usedPerms = eco.currentEmployeePermissionRecords
        .where((p) => p.status == 'Approved')
        .length;
    final remainingPerms = (2 - usedPerms).clamp(0, 2);
    final attendanceStatus = eco.todayLoginPunch != null ? 'Punched In' : 'Not Punched In Yet';

    return '''Hello **$firstName**! Here is your daily operational summary:

* **Today's Attendance:** **$attendanceStatus**
* **Active Tasks / To-Dos:** **$myTodos Pending**
* **Emergency Permissions:** **$remainingPerms / 2 Available** this month

How can I assist you with your tasks, shift timings, permissions, or team blockers today?''';
  }

  /// Generates an intelligent, personalized, and typo/grammar-tolerant response
  static CopilotResponse processQuery({
