      primaryKeywords: ['permission', 'gatepass', 'quota', 'permission balance'],
      secondaryKeywords: ['balance', 'remaining', 'hours', 'month', 'leave', 'urgent', 'allowed', 'limit'],
    );

    // ---------------------------------------------------------
