      normalizedInput: normalized,
      tokenWords: tokens,
      stemWords: stems,
      phrases: [
        'my tasks',
        'my todo',
        'pending work',
        'assigned to me',
        'what should i do',
        'daily task',
        'my checklist',
        'what to do today',
      ],
      primaryKeywords: ['task', 'todo', 'checklist'],
      secondaryKeywords: ['pending', 'assigned', 'duties', 'work list', 'items', 'sop checklist'],
    );

    // ---------------------------------------------------------
    // Intent 10: Staff Directory Lookup
    // ---------------------------------------------------------
